// ===== SW-017 Metadata Filter (§257/§457) =====
// Runs BEFORE retrieval. Emits the filter set the retriever applies; it does not
// itself query the repository.
const inp = $('When Called by WF-002').first().json;
const profile = inp.requirementProfile || {};
const cfg = inp.config || {};
const base = Object.assign({}, profile.filters || {});

if (cfg.metadataFiltering === false) {
  // §305 gate. Explicitly emit an EMPTY filter set and say so, rather than
  // quietly passing the derived filters through.
  return [{ json: Object.assign({}, inp, {
    filters: {}, filtersApplied: false,
    filterNote: 'metadataFiltering=false (§305): no metadata filter applied.' }) }];
}

// Only fields the repository can actually filter on are emitted. Inventing a filter
// the schema cannot honour would silently narrow retrieval to nothing.
const filters = {};
if (Array.isArray(profile.modules) && profile.modules.length) filters.modules = profile.modules;
if (profile.product) filters.product = profile.product;
if (Array.isArray(base.expandedTopics) && base.expandedTopics.length) filters.expandedTopics = base.expandedTopics;
if (base.authority) filters.authority = base.authority;
if (base.lifecycleState) filters.lifecycleState = base.lifecycleState;

return [{ json: Object.assign({}, inp, { filters, filtersApplied: Object.keys(filters).length > 0 }) }];
